const edition = globalThis.makeSubjectEdition({"subject":"golden-fleece","year":2013,"grade":"7-8","contest":"Золотое руно","letters":"ABC","count":60,"language":"kk","points":3,"tasksFile":"ZR_1213_KZ_7-8.pdf","answersFile":"reviewed-7-8-vkz.pdf","title":"Pax Germanica. Единство немецкой стихии","sourceFile":"sources/golden-fleece/2013/interactive-7-8-vkz.json","sections":[{"start":1,"title":"Тарих"},{"start":16,"title":"Әдебиет"},{"start":31,"title":"Күнделікті мәдениет"},{"start":46,"title":"Көркем мәдениет"}],"variant":"kz","editionSuffix":"vkz","editionLabel":"На казахском языке","reviewedKey":true}, [{"number":1,"question":"Герман императорлары мен рим папалары арасындағы қоғамдық бедел үшін күрес қандай құқыққа ие болу бақталастығынан туындаған?","choices":["Салық жинау","Князьдарды тағайындау","Діни қызметкерлерді тағайындау"],"answer":2,"title":"Спор о назначениях","steps":["Епископы обладали и церковной, и светской властью. Императоры и папы спорили, кто вправе вручать им знаки должности.","Соперничество за назначение духовных лиц называют борьбой за инвеституру."]},{"number":2,"question":"Император ІҮ Карлдың «Алтын булласы» кімдердің императорды сайлау тәртібін реттеді?","choices":["Курфюрсттардың","Мұрагерлік бойынша","Империяның барлық княздарының"],"answer":0,"title":"Выборы императора","steps":["Грамота Карла IV установила порядок голосования и перечислила князей, имевших голос. Их было семь.","Этих князей-избирателей называли курфюрстами."]},{"number":3,"question":"1555 жылы католиктер мен протестанттар арасындағы өзара қатынас жүйесін анықтайтын келісімге қол қойылған қала.","choices":["Нюрнберг","Мюнстер","Аугсбург"],"answer":2,"title":"Соглашение о вере","steps":["Имперские князья получили возможность выбирать между католицизмом и лютеранством. Решение закрепили в 1555 году.","По месту заключения оно известно как Аугсбургский религиозный мир."]},{"number":4,"question":"1867 жылы тәж кигізу жоралғысында І Франц Иосифке әулие Иштванның тәжін кигізу нені білдірді?","choices":["Венгрия мен Пруссияның бірігуін","Австрия империясының Австрия-Венгрия империясына айналуын","Венгрияның абсолюттік тәуелсіздігін"],"answer":1,"title":"Корона святого Иштвана","steps":["Это историческая корона венгерских монархов. В 1867 году Франц Иосиф стал королём Венгрии в рамках политического соглашения.","Соглашение превратило империю в дуалистическую Австро-Венгрию."]},{"number":5,"question":"Неміс әскерлерінің шабуыл жасаудағы стратегиялық жоспарының күл талқанын шығарған 1914 жылғы Марндағы шайқаста герман әскерінің жеңілуіне не себеп болды?","choices":["Одақтас әскерлерді түрмеден басқа жерге ауыстыру","Австрия-Венгрияның серб майданындағы сәтсіз шабуылдары","Шығыс Пруссиядағы орыс әскерлерінің шабуыл жасауы"],"answer":2,"title":"Два фронта","steps":["Германия стремилась быстро победить Францию до завершения русской мобилизации. Наступление на востоке ускорило переброску немецких войск.","Русские действия в Восточной Пруссии помогли ослабить давление на союзников во Франции."]},{"number":6,"question":"1648 жылғы Вестфаль бейбіт келісімі Германия үшін қандай дәуірдің аяқталғандығын білдірді?","choices":["Діни соғыстар","Сыртқы басып кіру","Шаруалар көтерілісі"],"answer":0,"title":"Мир после долгой войны","steps":["Война 1618–1648 годов начиналась на фоне конфликта католиков и протестантов. Мирные договоры закрепили право нескольких вероисповеданий.","Так Вестфальский мир положил конец эпохе крупных религиозных войн в Германии."]},{"number":7,"question":"Австрияның канцлері К.фон Меттернихті неліктен «Еуропаның ат айдаушысы» деп атаған?","choices":["Еуропа саясатына зор ықпал етуші болған","Жылқы өсірумен айналысқан","Көлік министрлігінің негізін қалаған"],"answer":0,"title":"Метафора кучера","steps":["Меттерних был одним из главных организаторов Венского конгресса. Потом он поддерживал согласованную политику европейских монархий.","Кучер направляет движение экипажа. Так подчеркнули влияние Меттерниха на европейскую политику."]},{"number":8,"question":"Германиядағы тұңғыш телеграф желісі Берлин – Франкфурт-на-Майне құрылысын жүргізген компанияның негізін салушылардың бірі болған неміс өнертапқышы кім?","choices":["К.Ф.Браун","Р.Бош","В.Сименс"],"answer":2,"title":"Линия телеграфа","steps":["Берлин и Франкфурт соединили электрическим телеграфом в середине XIX века. Работы выполняла фирма Siemens & Halske.","Фирму основал Вернер фон Сименс вместе с Иоганном Гальске."]},{"number":9,"question":"Реформацияның басталғандығының белгісі болған оқиғада М.Лютер Виттенбергтегі шіркеудің есігіне өзінің қандай шығармасын қағып қойды?","choices":["«Ерік-жігердің құлдықта болуы туралы»","«Христианның бостандығы туралы»","«Тоқсан бес тезис»"],"answer":2,"title":"Тезисы на дверях","steps":["Лютер спорил с продажей индульгенций и написал перечень положений для обсуждения. Они разошлись в печатных копиях.","Этот текст 1517 года называют «Девяносто пять тезисов»."]},{"number":10,"question":"ХҮ-ХҮІ ғасырлардағы Германиядағы жер иеленушілердің зорлықзомбылығы мен салықтың көптігіне қарсы шыққан шаруалар қозғалысының эмблемасы болған не?","choices":["Айыр","Башмақ","Алау"],"answer":1,"title":"Эмблема крестьян","steps":["Участники объединения носили на знамени изображение простой обуви со шнуровкой. По-немецки её называли Bundschuh.","Башмак противопоставляли дорогой обуви богатых землевладельцев."]},{"number":11,"question":"1895 жылы сәулелену туралы материалдарын жариялаған неміс физигі кім? Кейіннен ол сол адамның атымен аталатын болды.","choices":["Г.Герц","А.Эйнштейн","В.К.Рентген"],"answer":2,"title":"Невидимые лучи","steps":["Физик обнаружил излучение, способное проходить через некоторые непрозрачные материалы. С его помощью он получил снимок руки.","В 1895 году о лучах сообщил Вильгельм Конрад Рентген."]},{"number":12,"question":"Санкт-Петербург ғылым академиясының құрметті мүшесі болған неміс филологы, философы және мемлекеттік қайраткері кім?","choices":["И.Кант","И.В.Гёте","В.Гумбольт"],"answer":2,"title":"Филолог и дипломат","steps":["Один из братьев Гумбольдтов исследовал языки и занимался государственными делами. Другой известен путешествиями и географическими трудами.","Филологом и почётным членом академии был Вильгельм Гумбольдт."]},{"number":13,"question":"Бірінші дүниежүзілік соғыс кезінде неміс және британ флоты арасында болған Солтүстік теңіздегі шайқас.","choices":["Коронельск шайқасы","«Альбион» операциясы","Ютланд шайқасы"],"answer":2,"title":"Бой в Северном море","steps":["Крупные линейные флоты встретились у датского полуострова в мае 1916 года. После боя стороны по-разному оценивали результат.","Сражение назвали Ютландским."]},{"number":14,"question":"Екінші дүниежүзілік соғыс кезінде неміс әскері басып алған мемлекет.","choices":["Лихтенштейн","Люксембург","Швейцария"],"answer":1,"title":"Оккупация на западе","steps":["В мае 1940 года германские войска вторглись в страны на западной границе. Маленькое государство оказалось на пути к Франции.","Из предложенных стран была оккупирована территория Люксембурга."]},{"number":15,"question":"«Германдықтардың шығу тегі мен орналасқан жері» кітабын кім жазды?","choices":["Вергилий","Гай Юлий Цезарь","Публий Корнелий Тацит"],"answer":2,"title":"Книга о германцах","steps":["Римский историк описывает народы за пределами империи: где они живут, как управляют общинами и воюют. Трактат известен под коротким названием «Германия».","Автор — Публий Корнелий Тацит."]},{"number":16,"question":"Өткір айтылған әлеуметтік сындары үшін кейбір шығармаларына бундестаг тыйым салған жазушы кім?","choices":["Г.Гейне","Э.Т.А.Гофман","Ф.Шиллер"],"answer":0,"title":"Запрещённые книги","steps":["В 1835 году власти Германского союза запретили публикации авторов, связанных с «Молодой Германией». В их текстах критиковалось общество.","Среди этих авторов был Генрих Гейне."]},{"number":17,"question":"Төмендегі әдеби кейіпкерлердің қайсысы өзінің өмірбаянын жазған.","choices":["Етік киген мысық","Мысық Мурр","Мысық Шпигель"],"answer":1,"title":"Мемуары необычного автора","steps":["Автор мемуаров считает себя образованным и рассудительным. Листы его текста перемежаются с биографией музыканта Крейслера.","Мемуары пишет кот Мурр."]},{"number":18,"question":"Өзінің отбасы туралы жазған тұңғыш романы үшін Нобель сыйлығын алған жазушы кім?","choices":["Г.Белль","Г.Гауптман","Т.Манн"],"answer":2,"title":"Роман о семье","steps":["В «Будденброках» показана история нескольких поколений любекских купцов. Автор использовал материал из жизни собственной семьи.","За значение этого романа Нобелевскую премию получил Томас Манн."]},{"number":19,"question":"Француз республикасының азаматы атағы мен Ж.Дантонның қолы қойылған диплом алған неміс ақыны.","choices":["И.В.Гёте","Г.Гейне","Ф.Шиллер"],"answer":2,"title":"Почётный гражданин","steps":["В 1792 году французские революционные власти присудили почётное гражданство иностранным деятелям свободы. Среди них был автор пьесы «Разбойники».","Почести удостоился Фридрих Шиллер."]},{"number":20,"question":"Гётенің Фаустына Мефистофель бірінші рет ненің кейпінде келді?","choices":["Бұйра жүндес ит","Қара мысық","Қарға"],"answer":0,"title":"Загадочный спутник","steps":["После прогулки за Фаустом увязывается чёрная собака. В кабинете её облик меняется, и появляется искуситель.","Мефистофель впервые приходит в образе пуделя."]},{"number":21,"question":"И.В.Гётенің қандай шығармасына Л.ван Бетховен музыка жазды?","choices":["«Фауст»","«Эгмонт»","«Тавридадағы Ифигения»"],"answer":1,"title":"Музыка для пьесы","steps":["В 1810 году Бетховен написал увертюру и другие номера для постановки драмы Гёте о нидерландском противнике испанской власти.","Драма и музыка к ней называются «Эгмонт»."]},{"number":22,"question":"Неміс драматургы Ф.Шиллер, австрия жазушысы С.Цвейг өз шығармаларын арнаған королева кім?","choices":["Мария Терезия","Мария Антуанетта","Мария Стюарт"],"answer":2,"title":"Судьба королевы","steps":["Шиллер представил драматическое столкновение двух правительниц. Цвейг разобрал жизнь одной из них в книге о её судьбе.","Оба произведения посвящены Марии Стюарт."]},{"number":23,"question":"Шетелдік авторлардың прозалық шығармаларын пьесаларға айналдырған неміс тілді жазушы кім?","choices":["Б.Брехт","Г.Гауптман","Т.Манн"],"answer":0,"title":"Переделка в пьесу","steps":["Брехт перерабатывал чужие сюжеты для эпического театра. Среди его источников была проза Ярослава Гашека о Швейке.","Это пример того, как Бертольт Брехт превращал повествование в пьесу."]},{"number":24,"question":"Шындық жайттар ойдан шығарылған оқиғалармен араласып кеткен, Италия туралы очерк қалдырған неміс жазушысы кім?","choices":["В.Гауф","Г.Гейне","Э.Т.А.Гофман"],"answer":1,"title":"Путевые очерки","steps":["В «Путевых картинах» рассказчик соединяет подлинные впечатления, сатиру и вымысел. Часть очерков посвящена поездке из Мюнхена в Италию.","Автор этих очерков — Генрих Гейне."]},{"number":25,"question":"Тұңғыш ұлттық романтикалық опера жазған және басқа автордың опера туындысының кейіпкеріне айналған неміс әдебиетшісі кім?","choices":["Г.Гейне","Э.Т.А.Гофман","Л.Тик"],"answer":1,"title":"Писатель в двух операх","steps":["Автор «Ундины» сочинял и музыку, и прозу. Позднее Оффенбах соединил сюжеты из его произведений в новой опере.","Герой «Сказок Гофмана» — сам Эрнст Теодор Амадей Гофман."]},{"number":26,"question":"И.В.Гёте «Фауст» трагедиясында қандай қаланы «кішкентай Париж» деп атаған?","choices":["Дрезден","Лейпциг","Хемниц"],"answer":1,"title":"Город в «Фаусте»","steps":["В первой части трагедии Мефистофель приводит Фауста к веселящимся горожанам в погребок Ауэрбаха.","Погребок находится в Лейпциге. Этот город в пьесе называют маленьким Парижем."]},{"number":27,"question":"Үш қолжазбасы ЮНЕСКО-ның тізіміне енген немістің эпикалық поэмасы.","choices":["«Аннолид»","«Нибелунгтар туралы жыр»","«Хильдебранда туралы жыр»"],"answer":1,"title":"Три рукописи эпоса","steps":["Средневерхненемецкий эпос рассказывает о Зигфриде, Кримхильде и гибели бургундов. Сохранились несколько основных рукописей.","В список ЮНЕСКО включены три рукописи «Песни о Нибелунгах»."]},{"number":28,"question":"Р.Вагнердің барлық операларына жазылған либреттолардың авторы.","choices":["Р.Вагнер","П.Метастазио","К.И.Фридрих"],"answer":0,"title":"Автор оперных текстов","steps":["Вагнер замышлял оперу как единое произведение со сценой, поэзией и музыкой. Он самостоятельно превращал предания в драматические стихи.","Поэтому либретто своих опер он писал сам."]},{"number":29,"question":"Тентек балалар Макс пен Морица туралы балаларға арналған өлеңдер мен суреттер топтамасын шығарған кім?","choices":["Г.Гейне","В.Буш","Э.Т.А.Гофман"],"answer":1,"title":"Проделки сорванцов","steps":["Стихотворные подписи и последовательность рисунков вместе рассказывают о семи шалостях. История появилась в XIX веке.","«Макса и Морица» создал Вильгельм Буш."]},{"number":30,"question":"Бұл автордың шығармасындағы кейіпкерлер қонақ үйде ұйықтап қалып, қарақшылардың олжасына айналмас үшін бір-біріне әңгіме айтып отырған. Осы шығарманың авторы кім?","choices":["Э.Т.А.Гофман","Г.Гейне","В.Гауф"],"answer":2,"title":"Истории на постоялом дворе","steps":["В рамочном сюжете путники оказались в опасном месте и решили по очереди рассказывать истории. Так они бодрствовали до утра.","Сказочный цикл «Харчевня в Шпессарте» написал Вильгельм Гауф."]},{"number":31,"question":"«Конструкторлар патшасы» атанған неміс инженері, кәсіпкер кім?","choices":["Г.Даймлер","К.Бенц","В.Майбах"],"answer":2,"title":"Конструктор двигателей","steps":["Инженер работал с Даймлером над компактными двигателями и первыми автомобилями Mercedes. Позже его фамилия стала автомобильной маркой.","«Королём конструкторов» называли Вильгельма Майбаха."]},{"number":32,"question":"«Германиядағы орыстардың бірінші отаны» атанған немістің шипажай қаласы.","choices":["Швальбах","Висбаден","Баден-Баден"],"answer":2,"title":"Курорт русских гостей","steps":["В XIX веке к термальным источникам приезжали Тургенев, Достоевский и другие российские писатели. Здесь сложилась заметная русская община.","Курортный город — Баден-Баден."]},{"number":33,"question":"Үш мемлекет – Германия, Австрия және Швейцарияның шекарасында орналасқан көл.","choices":["Штарнбергзее","Цюрихтық","Боденскілік"],"answer":2,"title":"Озеро трёх стран","steps":["Зальцбургские озёра находятся в основном в Австрии, а Женевское — между Швейцарией и Францией. Нужны берега трёх немецкоязычных стран.","У всех трёх указанных стран есть берега Боденского озера."]},{"number":34,"question":"Швейцариядағы федеративтік бірлік қалай аталады?","choices":["Штат","Кантон","Графтық"],"answer":1,"title":"Части федерации","steps":["Швейцарские территории обладают своими конституциями и значительными полномочиями. Таких территорий 26.","Федеративную единицу Швейцарии называют кантоном."]},{"number":35,"question":"Еуропаның ең кіші мемлекеттерінің бірі Лихтенштейннің қаржылық жағдайының басты тірегі.","choices":["Киім үлгілерін жасау","Автомобиль өндірісі","Пошта маркаларын шығару"],"answer":2,"title":"Маленькие коллекционные вещи","steps":["Почтовые знаки княжества ценятся филателистами. Они продаются за пределами страны как коллекционные предметы.","Такую статью доходов обеспечивает выпуск почтовых марок."]},{"number":36,"question":"Германияның ресми әнұранының негізі болған ХҮІІІ ғасырдың соңында жазылған әуенді кім жазды?","choices":["Л.ван Бетховен","Й.Гайди","В.А.Моцарт"],"answer":1,"title":"Мелодия гимна","steps":["Мелодию сначала написали для песни в честь австрийского императора. Впоследствии её использовали для «Песни немцев».","Эта музыка принадлежит Йозефу Гайдну."]},{"number":37,"question":"Қай композитордың шығармалары дәстүрлі түрде Байрет музыка фестивалінің бағдарламасына еніп отырады?","choices":["И.Брамс","Ф.Лист","Р.Вагнер"],"answer":2,"title":"Композитор фестиваля","steps":["В Байройте построили особый театр для исполнения музыкальных драм. Первый фестиваль открылся постановкой тетралогии «Кольцо Нибелунга».","Репертуар фестиваля основан на произведениях Рихарда Вагнера."]},{"number":38,"question":"Вена қауіпті ауру індетінен құтылғаннан кейін император І Леопольд қандай ескерткішті орнатуға бұйрық берді?","choices":["«Шешек кресті»","«Жұқпалы ауру колоннасы»","«Безгек бағаны»"],"answer":1,"title":"Память об эпидемии","steps":["Венский император дал обет поставить памятник, если город переживёт эпидемию 1679 года. Барочная композиция с облаками находится на улице Грабен.","Она называется Чумной колонной."]},{"number":39,"question":"«Азат етуші-Сарбаз» монументі Берлиндегі қай саябақта орнатылған?","choices":["Трептов-парк","Тиргартен","Фолькспарк"],"answer":0,"title":"Воин с ребёнком","steps":["Центр советского мемориала занимает фигура бойца с ребёнком и мечом. У её ног изображена разбитая свастика.","Мемориал установлен в берлинском Трептов-парке."]},{"number":40,"question":"1972 жылы ХХ Олимпиадалық ойындар өткен немістің қаласы.","choices":["Берлин","Мюнхен","Франкфурт-на-Майне"],"answer":1,"title":"Игры 1972 года","steps":["В ФРГ построили олимпийские сооружения с известной прозрачной крышей. Они предназначались для летних Игр.","Хозяином Олимпиады 1972 года был Мюнхен."]},{"number":41,"question":"«Қазіргі заманғы кітап басып шығару» деп аталатын ескерткіш қай қалада орналасқан?","choices":["Берлин","Вена","Цюрих"],"answer":0,"title":"Стопка больших книг","steps":["Памятник из увеличенных книг напоминает об изобретении Гутенберга и немецкой литературе. Его создали для проекта «Аллея идей».","Композицию установили в Берлине."],"figure":{"src":"assets/golden-fleece/2013/interactive-7-8-kz/41.webp","alt":"Стопка больших книг · 41-тапсырмаға сурет","caption":"41-тапсырмаға сурет","width":113,"height":88}},{"number":42,"question":"Й.Гайднге, В.А.Моцартқа және Л.ван Бетховенге арналған ескерткіш қай қалада орнатылған?","choices":["Вена","Берлин","Бонн"],"answer":1,"title":"Памятник композиторам","steps":["Три музыканта относятся к венской классической школе. Однако изображённый памятник из светлого камня стоит за пределами Вены.","Памятник находится в Тиргартене в Берлине."],"figure":{"src":"assets/golden-fleece/2013/interactive-7-8-kz/42.webp","alt":"Памятник композиторам · 42-тапсырмаға сурет","caption":"42-тапсырмаға сурет","width":110,"height":88}},{"number":43,"question":"Фарфор мұражайы мен Күймелер мұражайы орналасқан парк.","choices":["Бельведер","Сан-Суси","Нимфенбург"],"answer":2,"title":"Кареты в парке","steps":["Бывшие придворные конюшни стали музеем карет. Рядом выставляют работы местной фарфоровой мануфактуры.","Музеи находятся в дворцово-парковом ансамбле Нимфенбург."],"figure":{"src":"assets/golden-fleece/2013/interactive-7-8-kz/43.webp","alt":"Кареты в парке · 43-тапсырмаға сурет","caption":"43-тапсырмаға сурет","width":111,"height":88}},{"number":44,"question":"Вена қаласындағы ескерткіштің көшірмесі болып табылатын және қаланың 300-жылдық құрметіне Санкт-Петербург қаласының маңына орнатылған ескерткіш қандай композиторға арналған?","choices":["Й.Гайдн","И.Штраус-ұлы","В.А.Моцарт"],"answer":1,"title":"Скрипка у памятника","steps":["На венском памятнике композитор изображён со скрипкой. В пригороде Петербурга он много лет выступал, поэтому там установили копию.","Композитора «Голубого Дуная» звали Иоганн Штраус-сын."],"figure":{"src":"assets/golden-fleece/2013/interactive-7-8-kz/44.webp","alt":"Скрипка у памятника · 44-тапсырмаға сурет","caption":"44-тапсырмаға сурет","width":111,"height":87}},{"number":45,"question":"Басында Литценбург деп аталып, кейінірек негізін салған адамның құрметіне аты өзгертілген сарай қалай аталады?","choices":["Шарлоттенбург","Шёнбрунн","Шёнхаузен"],"answer":0,"title":"Имя дворца","steps":["Резиденция Литценбург была построена для Софии Шарлотты. После её смерти дворцу дали новое имя.","Теперь берлинский дворец называется Шарлоттенбург."],"figure":{"src":"assets/golden-fleece/2013/interactive-7-8-kz/45.webp","alt":"Имя дворца · 45-тапсырмаға сурет","caption":"45-тапсырмаға сурет","width":110,"height":86}},{"number":46,"question":"Мына берілген суреттің авторы, «Көк салт атты» неміс суретшілер бірлестігінің негізін салушылардың бірі, орыс суретшісі кім?","choices":["К.Малевич","В.Кандинский","А.Явленский"],"answer":1,"title":"«Синий всадник»","steps":["В 1911 году вокруг художников-новаторов возникло мюнхенское объединение. Альманах подготовили Франц Марк и художник из России.","Русским сооснователем был Василий Кандинский."],"figure":{"src":"assets/golden-fleece/2013/interactive-7-8-kz/46.webp","alt":"«Синий всадник» · 46-тапсырмаға сурет","caption":"46-тапсырмаға сурет","width":115,"height":77}},{"number":47,"question":"Мына берілген суреттің авторы король ІІ Фридрихтің дәуіріндегі көріністерді бейнелеумен танымал. Бұл суретші кім?","choices":["В.Лейбль","Ф.Ленбах","А.Менцель"],"answer":2,"title":"Живопись эпохи короля","steps":["Художник исследовал одежду, мебель и распорядок времён Фридриха II. В его сценах тщательно передана придворная обстановка.","Так работал Адольф Менцель."],"figure":{"src":"assets/golden-fleece/2013/interactive-7-8-kz/47.webp","alt":"Живопись эпохи короля · 47-тапсырмаға сурет · Сол нысанның басқа фотосуреті","caption":"47-тапсырмаға сурет · Сол нысанның басқа фотосуреті","detailSrc":"assets/golden-fleece/2013/interactive-7-8-kz/47-detail.webp","width":620,"height":487}},{"number":48,"question":"Мына берілген суреттің авторы О.фон Бисмарктің 80-ге жуық портретін салған суретші. Ол кім?","choices":["Ф.Ленбах","В.Лейбль","А.Менцель"],"answer":0,"title":"Портреты канцлера","steps":["Портретист из Мюнхена много раз писал Бисмарка с натуры и по фотографиям. Он добивался выразительности лица на тёмном фоне.","Эту серию создал Франц фон Ленбах."],"figure":{"src":"assets/golden-fleece/2013/interactive-7-8-kz/48.webp","alt":"Портреты канцлера · 48-тапсырмаға сурет","caption":"48-тапсырмаға сурет","width":115,"height":91}},{"number":49,"question":"Мына берілген портреттің авторы ағылшын королінің сарайында жұмыс істеген. Ол қай суретші?","choices":["А.Дюрер","Кіші Г.Гольбейн","Үлкен Г.Гольбейн"],"answer":1,"title":"Художник при Тюдорах","steps":["Мастер из немецкоязычной семьи работал в Англии при Генрихе VIII. Ему поручали писать короля, придворных и дипломатов.","Это Ганс Гольбейн Младший."],"figure":{"src":"assets/golden-fleece/2013/interactive-7-8-kz/49.webp","alt":"Художник при Тюдорах · 49-тапсырмаға сурет","caption":"49-тапсырмаға сурет","width":94,"height":115}},{"number":50,"question":"Орыс императоры І Николайдың тапсырысы бойынша Санкт-Петербургтағы Жаңа Эрмитаж ғимаратының жобасын жасаған неміс сәулетшісі.","choices":["П.Беренс","К.Ф.Шинкель","Л.фон Кленце"],"answer":2,"title":"Архитектор Эрмитажа","steps":["Николай I заказал музейное здание, рассчитанное на показ коллекций. Монументальные формы здания и портик с атлантами выделяют его в ансамбле.","Проект Нового Эрмитажа выполнил Лео фон Кленце."],"figure":{"src":"assets/golden-fleece/2013/interactive-7-8-kz/50.webp","alt":"Архитектор Эрмитажа · 50-тапсырмаға сурет","caption":"50-тапсырмаға сурет","width":115,"height":88}},{"number":51,"question":"Бавария герцогының тапсырысын орындап, антикалық тарихтағы маңызды оқиға – Александр Македонский мен ІІІ Дарий әскерлерінің шайқасына арналған суретті салған кім?","choices":["А.Дюрер","А.Альтдорфер","М.Грюневальд"],"answer":1,"title":"Сражение на полотне","steps":["С высоты видны две армии, море и небо. Панорама изображает решающую битву Александра с войском Дария.","«Битву Александра при Иссе» написал Альбрехт Альтдорфер."],"figure":{"src":"assets/golden-fleece/2013/interactive-7-8-kz/51.webp","alt":"Сражение на полотне · 51-тапсырмаға сурет","caption":"51-тапсырмаға сурет","detailSrc":"assets/golden-fleece/2013/interactive-7-8-kz/51-detail.webp","width":475,"height":620}},{"number":52,"question":"Мына суретте бейнеленген саябақ ансамблі рококо дәуірінің бірегей ескерткіші болып табылады және оны «пруссия Версалі» деп атаған. Бұл жер қалай аталады?","choices":["Цвингер","Нимфенбург","Сан-Суси"],"answer":2,"title":"Прусский Версаль","steps":["Потсдамский дворец стоит над виноградными террасами. Его небольшие парадные залы относятся к рококо Фридриха Великого.","Ансамбль называется Сан-Суси."],"figure":{"src":"assets/golden-fleece/2013/interactive-7-8-kz/52.webp","alt":"Прусский Версаль · 52-тапсырмаға сурет","caption":"52-тапсырмаға сурет","width":115,"height":88}},{"number":53,"question":"Мына беріліп отырған сәулет құрылысының авторы өз еңбек жолын Германияда сарай ергежейлісі ретінде бастаған. Бұл кім?","choices":["А.Шлютер","К.Д.Азам","Ф.Кювилье"],"answer":2,"title":"Необычный путь архитектора","steps":["Мальчик попал при дворе баварского курфюрста в число придворных карликов. Позже он выучился архитектуре и оформлял дворцы в стиле рококо.","Этим архитектором стал Франсуа Кювилье."],"figure":{"src":"assets/golden-fleece/2013/interactive-7-8-kz/53.webp","alt":"Необычный путь архитектора · 53-тапсырмаға сурет","caption":"53-тапсырмаға сурет","width":115,"height":88}},{"number":54,"question":"Мына жерде беріліп отырған И.Ф.Овербектің суретінде қандай екі елдің мәдени байланысы аллегориялық тұрғыда бейнеленген?","choices":["Франция мен Австрия","Италия мен Германия","Венгрия мен Чехия"],"answer":1,"title":"Две аллегории","steps":["На картине две женщины сидят рядом и держатся за руки. За их спинами ландшафты отсылают к двум художественным традициям.","Овербек назвал произведение «Италия и Германия»."],"figure":{"src":"assets/golden-fleece/2013/interactive-7-8-kz/54.webp","alt":"Две аллегории · 54-тапсырмаға сурет","caption":"54-тапсырмаға сурет","width":133,"height":119}},{"number":55,"question":"Мына берілген суреттің авторы «Қалаларды, қамалдарды және қапшағайларды нығайтуды басқару» және тағы да басқа трактаттарымен де танымал. Бұл қандай суретші?","choices":["А.Дюрер","Кіші Л.Кранах","Үлкен Г.Гольбейн"],"answer":0,"title":"Художник и инженерия","steps":["Нюрнбергский мастер писал не только о пропорциях тела, но и о строительстве укреплений. Его интересовало применение геометрии.","Трактат о городах, замках и теснинах составил Альбрехт Дюрер."],"figure":{"src":"assets/golden-fleece/2013/interactive-7-8-kz/55.webp","alt":"Художник и инженерия · 55-тапсырмаға сурет","caption":"55-тапсырмаға сурет","width":145,"height":142}},{"number":56,"question":"Мына суреттің авторын орыс суретшісі И.Крамской қатты құрметтеген және ол туралы «оның өнер туындылары – ғылымдағы ұлы жаңалық сияқты» деген. Қай суретші туралы айтылып отыр?","choices":["А.Дюрер","Кіші Г.Гольбейн","М.Грюневальд"],"answer":1,"title":"Оценка портретиста","steps":["Крамской отмечал, что мастер северного Возрождения наблюдал человеческое лицо с точностью исследователя.","Речь о Гансе Гольбейне Младшем."],"figure":{"src":"assets/golden-fleece/2013/interactive-7-8-kz/56.webp","alt":"Оценка портретиста · 56-тапсырмаға сурет","caption":"56-тапсырмаға сурет","width":146,"height":143}},{"number":57,"question":"Мына суреттің авторы «Көк салт атты» суретшілер бірлестігімен қарым-қатынас жасаған. Кім жайында айтылып отыр?","choices":["В.Кандинский","М.Шагал","А.Явленский"],"answer":2,"title":"Участник выставок","steps":["Русский художник жил в Мюнхене и выставлял выразительные портреты и пейзажи рядом с Кандинским и его коллегами.","Участник выставок «Синего всадника» — Алексей Явленский."],"figure":{"src":"assets/golden-fleece/2013/interactive-7-8-kz/57.webp","alt":"Участник выставок · 57-тапсырмаға сурет","caption":"57-тапсырмаға сурет","width":115,"height":78}},{"number":58,"question":"Мына суреттің авторын замандастары Рафаэль Сантидің өзіне бәсекелес бола алады деп есептеген. Сөз болып отырған суретші кім?","choices":["Р.Менгс","В.фон Каульбах","А.Кауфман"],"answer":0,"title":"Соперник Рафаэля","steps":["Художник работал в Риме и Испании и стремился возродить классические принципы. Его фреска «Парнас» стала образцом неоклассицизма.","Это Антон Рафаэль Менгс."],"figure":{"src":"assets/golden-fleece/2013/interactive-7-8-kz/58.webp","alt":"Соперник Рафаэля · 58-тапсырмаға сурет","caption":"58-тапсырмаға сурет","width":87,"height":115}},{"number":59,"question":"Тікелей заттың өзіне қарап отырып, импрессионизм стилінде салған пейзаждарымен танымал неміс суретшісі.","choices":["Үлкен Л.Кранах","М.Либерман","К.Д.Фридрих"],"answer":1,"title":"Работа с натуры","steps":["Немецкий живописец писал мотивы Нидерландов и свои сады у озера. Свободные мазки передают изменчивый свет.","Эти работы характерны для Макса Либермана."],"figure":{"src":"assets/golden-fleece/2013/interactive-7-8-kz/59.webp","alt":"Работа с натуры · 59-тапсырмаға сурет","caption":"59-тапсырмаға сурет","width":115,"height":83}},{"number":60,"question":"Мына берілген суреттің авторы өзінің діни туындыларында адам мүсіні мен табиғат арасындағы бірегей үйлесімге қол жеткізе білді. Бұл суретші кім?","choices":["Кіші Г.Гольбейн","Үлкен Л.Кранах","М.Грюневальд"],"answer":1,"title":"Фигуры и природа","steps":["Мастер из Виттенберга помещал евангельские фигуры на фоне деревьев, гор и замков. Общий пейзаж помогает прочитать сюжет.","Этот приём заметен у Лукаса Кранаха Старшего."],"figure":{"src":"assets/golden-fleece/2013/interactive-7-8-kz/60.webp","alt":"Фигуры и природа · 60-тапсырмаға сурет","caption":"60-тапсырмаға сурет","width":75,"height":115}}]);
